using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2021, 9, 1) },
                new Student { LastName = "Baker", FirstMidName = "Arturo", EnrollmentDate = new DateTime(2019, 9, 1) }
            );
            _context.SaveChanges();
        }

        [Fact]
        public void Index_DefaultSort_ReturnsStudentsOrderedByLastName()
        {
            SeedStudents();
            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsStudentsDescending()
        {
            SeedStudents();
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsStudentsByDateAscending()
        {
            SeedStudents();
            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Index_DateDescSort_ReturnsStudentsByDateDescending()
        {
            SeedStudents();
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Alonso", model.First().LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            SeedStudents();
            var result = _controller.Index(null, null, "Alex", null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            SeedStudents();
            var result = _controller.Index(null, null, "Carson", null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_Paging_RespectsPageSize()
        {
            // Add more than 10 students
            for (int i = 0; i < 15; i++)
            {
                _context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = "Test",
                    EnrollmentDate = DateTime.Today
                });
            }
            _context.SaveChanges();

            var result = _controller.Index(null, null, null, 1) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal(10, model.Count);
            Assert.True(model.HasNextPage);
            Assert.False(model.HasPreviousPage);
        }

        [Fact]
        public void Index_Page2_HasPreviousPage()
        {
            for (int i = 0; i < 15; i++)
            {
                _context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = "Test",
                    EnrollmentDate = DateTime.Today
                });
            }
            _context.SaveChanges();

            var result = _controller.Index(null, null, null, 2) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal(5, model.Count);
            Assert.True(model.HasPreviousPage);
            Assert.False(model.HasNextPage);
        }

        [Fact]
        public void Index_NullSearchWithCurrentFilter_UsesCurrentFilter()
        {
            SeedStudents();
            var result = _controller.Index(null, "Alex", null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();

            var result = _controller.Details(student.ID) as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Test", model.LastName);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
        }

        [Fact]
        public void Create_Post_MinDateValue_AddsModelError()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as ViewResult;
            Assert.NotNull(result);
            Assert.Empty(_context.Students);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();

            var result = _controller.Edit(student.ID) as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Test", model.LastName);
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = new DateTime(2023, 1, 1) };
            _context.Students.Add(student);
            _context.SaveChanges();
            _context.Entry(student).State = EntityState.Detached;

            var updatedStudent = new Student
            {
                ID = student.ID,
                LastName = "Updated",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Edit(updatedStudent);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_MinDateValue_AddsModelError()
        {
            var student = new Student
            {
                ID = 1,
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Edit(student) as ViewResult;
            Assert.False(_controller.ModelState.IsValid);
