namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Drain any leftover notifications from other tests (static queue)
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }

            var result = _controller.GetNotifications();
            Assert.NotNull(result);
            var json = result.Value;
            Assert.NotNull(json);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            // Drain queue first
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }

            // Add notifications
            service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "System");
            service.SendNotification("Course", "100", "Math", EntityOperation.UPDATE, "System");

            var result = _controller.GetNotifications();
            Assert.NotNull(result);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);
            Assert.NotNull(result);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();
            Assert.IsType<ViewResult>(result);
        }
    }
}

using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain queue from other tests (static queue)
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithName()
        {
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_CreatesNotificationWithId()
        {
            _service.SendNotification("Course", "100", EntityOperation.UPDATE, "System");
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 100", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _service.SendNotification("Student", "1", null, EntityOperation.CREATE, null);
            var notification = _service.ReceiveNotification();
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageContainsCreated()
        {
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "User");
            var notification = _service.ReceiveNotification();
            Assert.Contains("has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_MessageContainsUpdated()
        {
            _service.SendNotification("Student", "1", "Test", EntityOperation.UPDATE, "User");
            var notification = _service.ReceiveNotification();
            Assert.Contains("has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_MessageContainsDeleted()
        {
            _service.SendNotification("Student", "1", "Test", EntityOperation.DELETE, "User");
            var notification = _service.ReceiveNotification();
            Assert.Contains("has been deleted", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _service.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleSent_ReturnsFIFO()
        {
            _service.SendNotification("A", "1", EntityOperation.CREATE);
            _service.SendNotification("B", "2", EntityOperation.UPDATE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op but should not throw
            var ex = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(ex);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() => service.Dispose());
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_OverflowEnforcesMaxQueueLength()
        {
            // Send more than 500 notifications
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Queue should be capped at 500
            int count = 0;
            while (_service.ReceiveNotification() != null) count++;
            Assert.True(count <= 500);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        private IQueryable<int> CreateSource(int count)
        {
            return Enumerable.Range(1, count).AsQueryable();
        }

        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.First());
            Assert.Equal(10, result.Last());
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 2, 10);
            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 3, 10);
            Assert.Equal(5, result.Count);
            Assert.Equal(21, result.First());
        }

        [Fact]
        public void TotalPages_CalculatedCorrectly()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void TotalPages_ExactDivision()
        {
            var source = CreateSource(20);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void TotalPages_SinglePage()
        {
            var source = CreateSource(5);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Equal(1, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 2, 10);
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 3, 10);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void PageIndex_IsCorrectlySet()
        {
            var source = CreateSource(25);
            var result = PaginatedList<int>.Create(source, 2, 10);
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SingleItem_SinglePage()
        {
            var source = CreateSource(1);
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Single(result);
            Assert.Equal(1, result.TotalPages);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2021, 9, 1) },
                new Student { LastName = "Baker", FirstMidName = "Arturo", EnrollmentDate = new DateTime(2019, 9, 1) }
            );
            _context.SaveChanges();
        }

        [Fact]
        public void Index_DefaultSort_ReturnsStudentsOrderedByLastName()
        {
            SeedStudents();
            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsStudentsDescending()
        {
            SeedStudents();
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsStudentsByDateAscending()
        {
            SeedStudents();
            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Index_DateDescSort_ReturnsStudentsByDateDescending()
        {
            SeedStudents();
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Alonso", model.First().LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            SeedStudents();
            var result = _controller.Index(null, null, "Alex", null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            SeedStudents();
            var result = _controller.Index(null, null, "Carson", null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_Paging_RespectsPageSize()
        {
            // Add more than 10 students
            for (int i = 0; i < 15; i++)
            {
                _context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = "Test",
                    EnrollmentDate = DateTime.Today
                });
            }
            _context.SaveChanges();

            var result = _controller.Index(null, null, null, 1) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal(10, model.Count);
            Assert.True(model.HasNextPage);
            Assert.False(model.HasPreviousPage);
        }

        [Fact]
        public void Index_Page2_HasPreviousPage()
        {
            for (int i = 0; i < 15; i++)
            {
                _context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = "Test",
                    EnrollmentDate = DateTime.Today
                });
            }
            _context.SaveChanges();

            var result = _controller.Index(null, null, null, 2) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Equal(5, model.Count);
            Assert.True(model.HasPreviousPage);
            Assert.False(model.HasNextPage);
        }

        [Fact]
        public void Index_NullSearchWithCurrentFilter_UsesCurrentFilter()
        {
            SeedStudents();
            var result = _controller.Index(null, "Alex", null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();

            var result = _controller.Details(student.ID) as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Test", model.LastName);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
        }

        [Fact]
        public void Create_Post_MinDateValue_AddsModelError()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as ViewResult;
            Assert.NotNull(result);
            Assert.Empty(_context.Students);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();

            var result = _controller.Edit(student.ID) as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Test", model.LastName);
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = new DateTime(2023, 1, 1) };
            _context.Students.Add(student);
            _context.SaveChanges();
            _context.Entry(student).State = EntityState.Detached;

            var updatedStudent = new Student
            {
                ID = student.ID,
                LastName = "Updated",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Edit(updatedStudent);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_MinDateValue_AddsModelError()
        {
            var student = new Student
            {
                ID = 1,
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Edit(student) as ViewResult;
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();

            var result = _controller.Delete(student.ID) as ViewResult;
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Test", model.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(student.ID);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Students);
        }
    }
}

using System;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _testWebRoot;

        public CoursesControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);

            _testWebRoot = Path.Combine(Directory.GetCurrentDirectory(), "test_webroot_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_testWebRoot);

            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_testWebRoot);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_testWebRoot);
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_testWebRoot))
            {
                try { Directory.Delete(_testWebRoot, true); } catch { }
            }
        }

        private Department SeedDepartment()
        {
            var dept = new Department { Name = "Engineering", Budget = 100000, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var dept = SeedDepartment();
            _context.Courses.Add(new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID });
            _context.SaveChanges();

            var result = _controller.Index() as ViewResult;
            var model = result.Model as System.Collections.Generic.List<Course>;
            Assert.Single(model);
            Assert.Equal("Chemistry", model.First().Title);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsView()
        {
            var dept = SeedDepartment();
            _context.Courses.Add(new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID });
            _context.SaveChanges();

            var result = _controller.Details(1050) as ViewResult;
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
        public void Create_Get_ReturnsView()
        {
            SeedDepartment();
            var result = _controller.Create() as ViewResult;
            Assert.NotNull(result);
            Assert.IsType<Course>(result.Model);
        }

        [Fact]
        public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Math", Credits = 4, DepartmentID = dept.DepartmentID };

            var result = _controller.Create(course, null);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void Create_Post_InvalidExtension_ReturnsModelError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2001, Title = "Science", Credits = 3, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = _controller.Create(course, mockFile.Object) as ViewResult;
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("valid image file", _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
        }

        [Fact]
        public void Create_Post_FileTooLarge_ReturnsModelError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2002, Title = "Art", Credits = 2, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

            var result = _controller.Create(course, mockFile.Object) as ViewResult;
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
        }

        [Fact]
        public void Create_Post_ValidFile_SavesCourseAndRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2003, Title = "Biology", Credits = 3, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Courses.Find(2003);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.Contains("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            var dept = SeedDepartment();
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 2004, Credits = 3, DepartmentID = dept.DepartmentID };

            var result = _controller.Create(course, null) as ViewResult;
            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            _context.Courses.Add(new Course { CourseID = 3000, Title = "History", Credits = 3, DepartmentID = dept.DepartmentID });
            _context.SaveChanges();

            var result = _controller.Edit(3000) as ViewResult;
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("History", model.Title);
