+using System;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Xunit;
+
+namespace ContosoUniversity.Tests.Services
+{
+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _service;
+
+        public NotificationServiceTests()
+        {
+            _service = new NotificationService();
+            // Drain queue from other tests (static queue)
+            while (_service.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            _service.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_WithDisplayName_CreatesNotificationWithName()
+        {
+            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("1", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Contains("John Doe", notification.Message);
+            Assert.Equal("Admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayName_CreatesNotificationWithId()
+        {
+            _service.SendNotification("Course", "100", EntityOperation.UPDATE, "System");
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("ID: 100", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_NullUserName_DefaultsToSystem()
+        {
+            _service.SendNotification("Student", "1", null, EntityOperation.CREATE, null);
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void SendNotification_CreateOperation_MessageContainsCreated()
+        {
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "User");
+            var notification = _service.ReceiveNotification();
+            Assert.Contains("has been created", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_UpdateOperation_MessageContainsUpdated()
+        {
+            _service.SendNotification("Student", "1", "Test", EntityOperation.UPDATE, "User");
+            var notification = _service.ReceiveNotification();
+            Assert.Contains("has been updated", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_DeleteOperation_MessageContainsDeleted()
+        {
+            _service.SendNotification("Student", "1", "Test", EntityOperation.DELETE, "User");
+            var notification = _service.ReceiveNotification();
+            Assert.Contains("has been deleted", notification.Message);
+        }
+
+        [Fact]
+        public void ReceiveNotification_EmptyQueue_ReturnsNull()
+        {
+            var result = _service.ReceiveNotification();
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void ReceiveNotification_MultipleSent_ReturnsFIFO()
+        {
+            _service.SendNotification("A", "1", EntityOperation.CREATE);
+            _service.SendNotification("B", "2", EntityOperation.UPDATE);
+
+            var first = _service.ReceiveNotification();
+            var second = _service.ReceiveNotification();
+
+            Assert.Equal("A", first.EntityType);
+            Assert.Equal("B", second.EntityType);
+        }
+
+        [Fact]
+        public void MarkAsRead_DoesNotThrow()
+        {
+            // MarkAsRead is a no-op but should not throw
+            var ex = Record.Exception(() => _service.MarkAsRead(1));
+            Assert.Null(ex);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            var service = new NotificationService();
+            var ex = Record.Exception(() => service.Dispose());
+            Assert.Null(ex);
+        }
+
+        [Fact]
+        public void SendNotification_OverflowEnforcesMaxQueueLength()
+        {
+            // Send more than 500 notifications
+            for (int i = 0; i < 510; i++)
+            {
+                _service.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
+            }
+
+            // Queue should be capped at 500
+            int count = 0;
+            while (_service.ReceiveNotification() != null) count++;
+            Assert.True(count <= 500);
+        }
+    }
+}
+

