using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            DbInitializer.Initialize(_context);
            Assert.Equal(8, _context.Students.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            DbInitializer.Initialize(_context);
            Assert.Equal(5, _context.Instructors.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            DbInitializer.Initialize(_context);
            Assert.Equal(4, _context.Departments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            DbInitializer.Initialize(_context);
            Assert.Equal(7, _context.Courses.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            DbInitializer.Initialize(_context);
            Assert.True(_context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            DbInitializer.Initialize(_context);
            Assert.Equal(3, _context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            DbInitializer.Initialize(_context);
            Assert.Equal(8, _context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            // Seed once
            DbInitializer.Initialize(_context);
            var studentCount = _context.Students.Count();

            // Seed again - should be no-op
            DbInitializer.Initialize(_context);
            Assert.Equal(studentCount, _context.Students.Count());
        }
    }
}

using System;
using System.Collections.Generic;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student { LastName = "Smith", FirstMidName = "John" };
            Assert.Equal("Smith, John", student.FullName);
        }

        [Fact]
        public void FullName_Instructor_ReturnsCorrectFormat()
        {
            var instructor = new Instructor { LastName = "Doe", FirstMidName = "Jane" };
            Assert.Equal("Doe, Jane", instructor.FullName);
        }
    }

    public class StudentModelTests
    {
        [Fact]
        public void Student_HasEnrollmentDate()
        {
            var date = new DateTime(2023, 9, 1);
            var student = new Student { EnrollmentDate = date };
            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Student_Enrollments_CanBeSet()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Today,
                Enrollments = new List<Enrollment>
                {
                    new Enrollment { EnrollmentID = 1, CourseID = 100, Grade = Grade.A }
                }
            };
            Assert.Single(student.Enrollments);
        }
    }

    public class InstructorModelTests
    {
        [Fact]
        public void Instructor_HasHireDate()
        {
            var date = new DateTime(2010, 3, 15);
            var instructor = new Instructor { HireDate = date };
            Assert.Equal(date, instructor.HireDate);
        }

        [Fact]
        public void Instructor_CourseAssignments_CanBeSet()
        {
            var instructor = new Instructor
            {
                LastName = "Test",
                FirstMidName = "Inst",
                HireDate = DateTime.Today,
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1, InstructorID = 1 }
                }
            };
            Assert.Single(instructor.CourseAssignments);
        }

        [Fact]
        public void Instructor_OfficeAssignment_CanBeSet()
        {
            var instructor = new Instructor
            {
                LastName = "Test",
                FirstMidName = "Inst",
                HireDate = DateTime.Today,
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
        }
    }

    public class CourseModelTests
    {
        [Fact]
        public void Course_Properties_SetCorrectly()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/uploads/test.jpg"
            };
            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/uploads/test.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_NavigationProperties_CanBeSet()
        {
            var dept = new Department { DepartmentID = 1, Name = "Engineering" };
            var course = new Course
            {
                CourseID = 100,
                Title = "Test",
                Credits = 3,
                DepartmentID = 1,
                Department = dept,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            Assert.Equal(dept, course.Department);
            Assert.Empty(course.Enrollments);
            Assert.Empty(course.CourseAssignments);
        }
    }

    public class DepartmentModelTests
    {
        [Fact]
        public void Department_Properties_SetCorrectly()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 5,
                RowVersion = new byte[] { 1, 2, 3, 4 }
            };
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(5, dept.InstructorID);
            Assert.Equal(new byte[] { 1, 2, 3, 4 }, dept.RowVersion);
        }

        [Fact]
        public void Department_Administrator_CanBeSet()
        {
            var instructor = new Instructor { LastName = "Admin", FirstMidName = "Dept", HireDate = DateTime.Today };
            var dept = new Department
            {
                Name = "Test",
                Administrator = instructor,
                Courses = new List<Course>()
            };
            Assert.Equal(instructor, dept.Administrator);
            Assert.Empty(dept.Courses);
        }
    }

    public class EnrollmentModelTests
    {
        [Fact]
        public void Enrollment_Properties_SetCorrectly()
        {
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 5,
                Grade = Grade.B
            };
            Assert.Equal(1, enrollment.EnrollmentID);
            Assert.Equal(100, enrollment.CourseID);
            Assert.Equal(5, enrollment.StudentID);
            Assert.Equal(Grade.B, enrollment.Grade);
        }

        [Fact]
        public void Enrollment_Grade_CanBeNull()
        {
            var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 100, StudentID = 5 };
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Enrollment_NavigationProperties_CanBeSet()
        {
            var course = new Course { CourseID = 100, Title = "Test", Credits = 3 };
            var student = new Student { LastName = "S", FirstMidName = "T", EnrollmentDate = DateTime.Today };
            var enrollment = new Enrollment
            {
                CourseID = 100,
                StudentID = 1,
                Course = course,
                Student = student
            };
            Assert.Equal(course, enrollment.Course);
            Assert.Equal(student, enrollment.Student);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_Properties_SetCorrectly()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "New student created",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = false,
                ReadAt = null
            };
            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New student created", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void Notification_ReadAt_CanBeSet()
        {
            var readAt = DateTime.Now;
            var notification = new Notification
            {
                EntityType = "Course",
                EntityId = "1",
                Operation = "UPDATE",
                Message = "Updated",
                CreatedAt = DateTime.Now,
                IsRead = true,
                ReadAt = readAt
            };
            Assert.True(notification.IsRead);
            Assert.Equal(readAt, notification.ReadAt);
        }
    }

    public class EntityOperationEnumTests
    {
        [Theory]
        [InlineData(EntityOperation.CREATE, "CREATE")]
        [InlineData(EntityOperation.UPDATE, "UPDATE")]
        [InlineData(EntityOperation.DELETE, "DELETE")]
        public void EntityOperation_HasExpectedStringValues(EntityOperation op, string expected)
        {
            Assert.Equal(expected, op.ToString());
        }
    }

    public class OfficeAssignmentModelTests
    {
        [Fact]
        public void OfficeAssignment_Properties_SetCorrectly()
        {
            var instructor = new Instructor { LastName = "T", FirstMidName = "I", HireDate = DateTime.Today };
            var office = new OfficeAssignment
            {
                InstructorID = 1,
                Location = "Thompson 304",
                Instructor = instructor
            };
            Assert.Equal(1, office.InstructorID);
            Assert.Equal("Thompson 304", office.Location);
            Assert.Equal(instructor, office.Instructor);
        }
    }

    public class CourseAssignmentModelTests
    {
        [Fact]
        public void CourseAssignment_Properties_SetCorrectly()
        {
            var ca = new CourseAssignment
            {
                InstructorID = 1,
                CourseID = 100,
                Instructor = new Instructor { LastName = "T", FirstMidName = "I", HireDate = DateTime.Today },
                Course = new Course { CourseID = 100, Title = "Test", Credits = 3 }
            };
            Assert.Equal(1, ca.InstructorID);
            Assert.Equal(100, ca.CourseID);
            Assert.NotNull(ca.Instructor);
            Assert.NotNull(ca.Course);
        }
    }

    public class AssignedCourseDataTests
    {
        [Fact]
        public void AssignedCourseData_Properties_SetCorrectly()
        {
            var data = new AssignedCourseData
            {
                CourseID = 100,
                Title = "Chemistry",
                Assigned = true
            };
            Assert.Equal(100, data.CourseID);
            Assert.Equal("Chemistry", data.Title);
            Assert.True(data.Assigned);
        }
    }

    public class InstructorIndexDataTests
    {
        [Fact]
        public void InstructorIndexData_Properties_CanBeSet()
        {
            var data = new InstructorIndexData
            {
                Instructors = new List<Instructor>(),
                Courses = new List<Course>(),
                Enrollments = new List<Enrollment>()
            };
            Assert.Empty(data.Instructors);
            Assert.Empty(data.Courses);
            Assert.Empty(data.Enrollments);
        }
    }

    public class EnrollmentDateGroupTests
    {
        [Fact]
        public void EnrollmentDateGroup_Properties_SetCorrectly()
        {
            var date = new DateTime(2023, 9, 1);
            var group = new EnrollmentDateGroup
            {
                EnrollmentDate = date,
                StudentCount = 5
            };
            Assert.Equal(date, group.EnrollmentDate);
            Assert.Equal(5, group.StudentCount);
        }

        [Fact]
        public void EnrollmentDateGroup_EnrollmentDate_CanBeNull()
        {
            var group = new EnrollmentDateGroup { EnrollmentDate = null, StudentCount = 0 };
            Assert.Null(group.EnrollmentDate);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ErrorViewModel_ShowRequestId_TrueWhenNotEmpty()
        {
            var model = new ErrorViewModel { RequestId = "ABC123" };
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_FalseWhenNull()
        {
            var model = new ErrorViewModel { RequestId = null };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_FalseWhenEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };
            Assert.False(model.ShowRequestId);
        }
    }
}

using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            _context.Students.Add(new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Today
            });
            _context.SaveChanges();

            var student = _context.Students.First();
            Assert.Equal("Test", student.LastName);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            _context.Instructors.Add(new Instructor
            {
                LastName = "Test",
                FirstMidName = "Instructor",
                HireDate = DateTime.Today
            });
            _context.SaveChanges();

            var instructor = _context.Instructors.First();
            Assert.Equal("Test", instructor.LastName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            _context.Courses.Add(new Course
            {
                CourseID = 5000,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            });
            _context.SaveChanges();

            var course = _context.Courses.Find(5000);
            Assert.Equal("Test Course", course.Title);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            _context.Departments.Add(new Department
            {
                Name = "Test Dept",
                Budget = 50000,
                StartDate = DateTime.Today
            });
            _context.SaveChanges();

            var dept = _context.Departments.First();
            Assert.Equal("Test Dept", dept.Name);
        }

        [Fact]
        public void CourseAssignment_CompositeKey_Works()
        {
            var instructor = new Instructor { LastName = "T", FirstMidName = "I", HireDate = DateTime.Today };
            _context.Instructors.Add(instructor);
            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 9000, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.CourseAssignments.Add(new CourseAssignment
            {
                CourseID = course.CourseID,
                InstructorID = instructor.ID
            });
            _context.SaveChanges();

            var ca = _context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(ca);
        }

        [Fact]
        public void OfficeAssignment_OneToOne_Works()
        {
            var instructor = new Instructor
            {
                LastName = "T",
                FirstMidName = "I",
                HireDate = DateTime.Today,
                OfficeAssignment = new OfficeAssignment { Location = "Room 100" }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var loaded = _context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.ID == instructor.ID);
            Assert.Equal("Room 100", loaded.OfficeAssignment.Location);
        }

        [Fact]
        public void Enrollment_Relationships_Work()
        {
            var student = new Student { LastName = "S", FirstMidName = "T", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 8000, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.Enrollments.Add(new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            });
            _context.SaveChanges();

            var enrollment = _context.Enrollments.First();
            Assert.Equal(Grade.A, enrollment.Grade);
            Assert.Equal(student.ID, enrollment.StudentID);
            Assert.Equal(course.CourseID, enrollment.CourseID);
        }

        [Fact]
        public void Notification_CanBeStoredAndRetrieved()
        {
            _context.Notifications.Add(new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            });
            _context.SaveChanges();

            var notification = _context.Notifications.First();
            Assert.Equal("Student", notification.EntityType);
        }
    }
}

