        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            var dept = SeedDepartment();
            _context.Courses.Add(new Course { CourseID = 4001, Title = "Geography", Credits = 3, DepartmentID = dept.DepartmentID });
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(4001);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Courses.Find(4001));
        }

        [Fact]
        public void DeleteConfirmed_WithImagePath_RemovesCourse()
        {
            var dept = SeedDepartment();
            _context.Courses.Add(new Course
            {
                CourseID = 4002,
                Title = "Art",
                Credits = 2,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/nonexistent.jpg"
            });
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(4002);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Courses.Find(4002));
        }

        [Fact]
        public void Edit_Post_FileTooLarge_ReturnsModelError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3003, Title = "Drama", Credits = 2, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("big.png");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024);

            var result = _controller.Edit(course, mockFile.Object) as ViewResult;
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
        }

        [Fact]
        public void Edit_Post_ValidFile_SavesAndRedirects()
        {
            var dept = SeedDepartment();
            _context.Courses.Add(new Course { CourseID = 3004, Title = "Dance", Credits = 2, DepartmentID = dept.DepartmentID });
            _context.SaveChanges();
            _context.ChangeTracker.Clear();

            var course = new Course { CourseID = 3004, Title = "Dance Updated", Credits = 2, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("new.png");
            mockFile.Setup(f => f.Length).Returns(2048);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(course, mockFile.Object);
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            var dept = SeedDepartment();
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 3005, Credits = 3, DepartmentID = dept.DepartmentID };

            var result = _controller.Edit(course, null) as ViewResult;
            Assert.NotNull(result);
        }
    }
}

